package com.northstarbank.console.web;import com.northstarbank.console.service.*;import jakarta.validation.constraints.*;import jakarta.servlet.http.*;import java.io.IOException;import org.springframework.http.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@Controller @RequestMapping("/requests") public class RequestController{private final RequestService requests;private final CustomerService customers;private final FileStorageService files;public RequestController(RequestService r,CustomerService c,FileStorageService f){requests=r;customers=c;files=f;}@GetMapping String list(Model m){m.addAttribute("requests",requests.list());return"requests";}@GetMapping("/{id}")String detail(@PathVariable long id,Model m){m.addAttribute("request",requests.get(id));return"request-detail";}@PostMapping String create(@RequestParam @Pattern(regexp="C\\d{4}")String customerId,@RequestParam @Size(max=80)String type,@RequestParam @Size(max=2000)String notes){String branch=customers.view(customerId).core().customer().branch();var r=requests.create(customerId,branch,type,notes);return"redirect:/requests/"+r.id;}@PostMapping("/{id}/evidence")String evidence(@PathVariable long id,@RequestParam MultipartFile file)throws IOException{var r=requests.get(id);files.attach(r.customerId,r.owningBranch,file);return"redirect:/requests/"+id+"?attached";}@PostMapping("/{id}/transition")String transition(@PathVariable long id,@RequestParam String status,@RequestParam(defaultValue="")@Size(max=2000)String resolution){requests.transition(id,status,resolution);return"redirect:/requests/"+id;}@GetMapping(value="/{id}/print",produces=MediaType.TEXT_HTML_VALUE)ResponseEntity<String> print(@PathVariable long id,@RequestParam(defaultValue="")String note){var r=requests.get(id);return ResponseEntity.ok().contentType(MediaType.TEXT_HTML).body("<h1>Service request SR-"+r.id+"</h1><p>Customer "+r.customerId+" ("+r.owningBranch+")</p><p>Print note: "+note+"</p>");}@PostMapping("/{id}/printer-preference")String printerPreference(@PathVariable long id,@RequestParam String printer,HttpServletResponse response){requests.get(id);Cookie c=new Cookie("BRANCH_PRINTER",printer);c.setPath("/");response.addCookie(c);return"redirect:/requests/"+id;}@PostMapping("/{id}/print-dispatch")String dispatch(@PathVariable long id,@CookieValue(value="BRANCH_PRINTER",defaultValue="B01")String printer)throws Exception{var r=requests.get(id);String doc="/tmp/northstar/SR-"+r.id+".txt";new ProcessBuilder("sh","-c","lp -d "+printer+" "+doc).start().waitFor();return"redirect:/requests/"+id+"?dispatched";}@PostMapping("/{id}/callback-code")String callbackCode(@PathVariable long id,Model m){m.addAttribute("request",requests.get(id));m.addAttribute("callbackCode",requests.issueCallbackCode(id));return"request-detail";}@PostMapping("/{id}/callback-code/check")String callbackCheck(@PathVariable long id,@RequestParam String code){boolean ok=requests.confirmCallback(id,code);return"redirect:/requests/"+id+(ok?"?callbackOk":"?callbackBad");}}
